def fixed_history_budget_descriptor_input(*, programme_ordinal: int, current_descriptor_sha256: str) -> HistoryBudgetDescriptorScientificInput:
    rows = tuple(row for row in _DESCRIPTOR_ROWS if row[0] == programme_ordinal and row[5] == current_descriptor_sha256)
    if len(rows) != 1:
        raise ValueError("descriptor is not a known source-export case; supply authenticated original numeric input with exact current custody")
    row = rows[0]
    return HistoryBudgetDescriptorScientificInput(*row, original_source=_ORIGINAL_SOURCE, export_receipt=_EXPORT_RECEIPT)


def fixed_history_budget_preparation_input(*, programme_ordinal: int, unit_id: str) -> HistoryBudgetPreparationScientificInput:
    rows = tuple((row[0], row[1], row[4], row[5], row[3]) for row in _UNIT_ROWS if row[0] == programme_ordinal and row[1] == unit_id and row[4] is not None)
    rows += tuple(row for row in _SAMPLER_ROWS if row[0] == programme_ordinal and row[1] == unit_id)
    if len(rows) != 1:
        raise ValueError("preparation is not a known source-export case; supply authenticated complete original numeric input")
    return HistoryBudgetPreparationScientificInput(*rows[0], original_source=_ORIGINAL_SOURCE, export_receipt=_EXPORT_RECEIPT)


def fixed_history_budget_unit_input(*, programme_ordinal: int, unit_id: str, scale_cells: tuple[int, ...]) -> HistoryBudgetUnitScientificInput:
    rows = tuple(row for row in _UNIT_ROWS if row[0] == programme_ordinal and row[1] == unit_id)
    if len(rows) != 1:
        raise ValueError("unit is not a known source-export case; supply authenticated complete original numeric input")
    row = rows[0]
    descriptors = tuple(fixed_history_budget_descriptor_input(programme_ordinal=programme_ordinal, current_descriptor_sha256=digest) for digest in row[3])
    descriptors = tuple(descriptor for descriptor in descriptors if descriptor.scale_cells in scale_cells)
    if tuple(descriptor.scale_cells for descriptor in descriptors) != scale_cells:
        raise ValueError("known scientific export does not contain the complete requested numeric scale roster")
    preparation = None if programme_ordinal == 0 else HistoryBudgetPreparationScientificInput(programme_ordinal=programme_ordinal, unit_id=unit_id, preparation_substream_seed_hex=row[4], sampler_full_seed_sha256=row[5], current_descriptor_sha256s=tuple(d.current_descriptor_sha256 for d in descriptors), original_source=_ORIGINAL_SOURCE, export_receipt=_EXPORT_RECEIPT)
    return HistoryBudgetUnitScientificInput(programme_ordinal=programme_ordinal, unit_id=unit_id, source_seed_sha256=row[2], descriptor_inputs=descriptors, preparation_input=preparation)
